/**
 * Styles for the pet's settings card.
 *
 * These are the shipped card's own values, copied member for member, because a
 * card that approximates them reads as a different component beside its
 * neighbours: a few pixels of extra padding and a larger radius are enough to
 * break the row. The one addition is the grouping used by the pet's own panel;
 * everything else keeps the shipped geometry.
 *
 * The class prefix stays `cdpc-` rather than reusing the section's hashed CSS
 * Module names, which a package outside this repository cannot import.
 */
/** Stylesheet installed once per plugin activation. */
export declare const CARD_STYLES = "\n.cdpc {\n  list-style: none;\n  border: 0.5px solid var(--dsw-alias-border-l4);\n  border-radius: 16px;\n  background: var(--dsw-alias-bg-layer-3);\n  transition: border-color .16s, background .16s;\n}\n.cdpc:hover { border-color: var(--dsw-alias-label-dimmed); }\n.cdpc[data-open='true'] {\n  background: var(--dsw-alias-bg-layer-2);\n  border-color: var(--dsw-alias-label-dimmed);\n}\n.cdpc-head {\n  width: 100%;\n  appearance: none;\n  border: 0;\n  background: none;\n  font: inherit;\n  color: inherit;\n  text-align: left;\n  cursor: pointer;\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  padding: 14px 16px;\n  border-radius: 12px;\n}\n.cdpc-head:focus-visible {\n  outline: 2px solid var(--dsw-alias-brand-primary);\n  outline-offset: -2px;\n}\n.cdpc-headtext {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n.cdpc-name {\n  font-size: 15px;\n  font-weight: 600;\n  line-height: 1.4;\n  color: var(--dsw-alias-label-primary);\n}\n.cdpc-desc {\n  font-size: 13px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-tertiary);\n}\n.cdpc-chevron {\n  flex: none;\n  color: var(--dsw-alias-label-tertiary);\n  transition: transform .16s;\n}\n.cdpc[data-open='true'] .cdpc-chevron { transform: rotate(180deg); }\n.cdpc-body {\n  border-top: 0.5px solid var(--dsw-alias-border-l2);\n  margin: 0 16px;\n  padding-bottom: 8px;\n}\n.cdpc-group { padding: 12px 0; }\n.cdpc-group + .cdpc-group { border-top: 0.5px solid var(--dsw-alias-border-l2); }\n.cdpc-grouptitle {\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-tertiary);\n  margin-bottom: 8px;\n}\n.cdpc-row {\n  display: grid;\n  grid-template-columns: 1fr auto;\n  align-items: center;\n  gap: 2px 16px;\n  padding: 6px 0;\n}\n.cdpc-label {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  font-size: 13px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-primary);\n}\n.cdpc-hint {\n  grid-column: 1;\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-tertiary);\n}\n.cdpc-control {\n  grid-column: 2;\n  grid-row: 1 / span 2;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n.cdpc-number {\n  width: 88px;\n  padding: 4px 8px;\n  font: inherit;\n  font-size: 13px;\n  line-height: 1.5;\n  color: inherit;\n  background: none;\n  border: 1px solid var(--dsw-alias-border-l2);\n  border-radius: 8px;\n}\n.cdpc-slider { display: flex; align-items: center; gap: 10px; }\n.cdpc-slider input[type='range'] { width: 150px; accent-color: var(--dsw-alias-brand-primary); }\n.cdpc-value {\n  min-width: 32px;\n  text-align: right;\n  font-size: 13px;\n  line-height: 1.5;\n  font-variant-numeric: tabular-nums;\n  color: var(--dsw-alias-label-tertiary);\n}\n.cdpc-corners { display: grid; grid-template-columns: repeat(2, 18px); gap: 3px; }\n.cdpc-corner {\n  width: 18px;\n  height: 18px;\n  padding: 0;\n  cursor: pointer;\n  border: 1px solid var(--dsw-alias-border-l4);\n  border-radius: 4px;\n  background-color: var(--dsw-alias-bg-layer-3);\n  background-image: radial-gradient(circle at center, var(--dsw-alias-label-dimmed) 2px, transparent 2px);\n}\n.cdpc-corner:hover { border-color: var(--dsw-alias-label-dimmed); }\n.cdpc-corner[data-active='true'] {\n  background-color: var(--dsw-alias-brand-primary);\n  border-color: var(--dsw-alias-brand-primary);\n  background-image: radial-gradient(circle at center, #fff 2px, transparent 2px);\n}\n.cdpc-reset {\n  appearance: none;\n  border: 0;\n  background: none;\n  padding: 0;\n  font: inherit;\n  font-size: 12px;\n  line-height: 1.5;\n  cursor: pointer;\n  color: var(--dsw-alias-label-tertiary);\n  text-decoration: underline dotted;\n}\n.cdpc-reset:hover { color: var(--dsw-alias-label-primary); }\n.cdpc-footer {\n  display: flex;\n  align-items: center;\n  justify-content: flex-end;\n  gap: 8px;\n  padding: 12px 0 4px;\n  border-top: 0.5px solid var(--dsw-alias-border-l2);\n}\n.cdpc-status {\n  flex: 1;\n  min-width: 0;\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-tertiary);\n}\n.cdpc-error {\n  flex: 1;\n  min-width: 0;\n  font-size: 12px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-error);\n}\n.cdpc-pending {\n  flex: none;\n  font-size: 13px;\n  line-height: 1.5;\n  color: var(--dsw-alias-label-tertiary);\n}\n";
